def rrf(rank_lists, k=60):
    score = {}
    for ranks in rank_lists:
        for rank, doc in enumerate(ranks, 1):
            score[doc] = score.get(doc, 0.0) + 1.0 / (k + rank)
    return sorted(score, key=lambda d: score[d], reverse=True)

rl = [['a', 'b', 'c'], ['c', 'a', 'd']]
order = rrf(rl)
print('order:', order)          # 期望 c 在前
# 验证「向量分值大但排名低」不会碾压：只比较排名贡献
big = rrf([['x'], ['x']*50])     # x 在路一第1、路二第1
low = rrf([['y'], ['y']*50])     # 同样两路第1
print('x==y dominated by rank:', abs(big['x']-low['y']) < 1e-9)

def fixed_chunk(text, size, overlap):
    step = max(1, size - overlap)
    n = len(text)
    if n <= size:
        return [text] if n > 0 else [''.join(text)]
    return [text[i:i+size] for i in range(0, n - size + 1, step)]

def fragment_rate(L, E, size, overlap):
    step = max(1, size - overlap)
    return max(1.0, E / step)

for tl, ev in [(150, 100), (1000, 50), (1000, 400)]:
    ch = fixed_chunk('x'*tl, 200, 20)
    print(f'L={tl}: 块数 {len(ch)}, 碎片率 {fragment_rate(tl, ev, 200, 20):.2f}')
